function buildSupervisor({ kind, signal, started, now = () => performance.now() } = {}, dependencies) {
  if (!['api', 'cli'].includes(kind) || typeof now !== 'function'
      || (signal !== undefined && !(signal instanceof AbortSignal))) fail('INPUT', 'LAUNCH');
  const readNow = () => {
    const current = now();
    if (!Number.isFinite(current) || current < last) fail('INTERNAL', 'LAUNCH');
    last = current;
    return current;
  };
  let last = -Infinity;
  const initial = readNow();
  started ??= initial;
  if (!Number.isFinite(started) || started > initial) fail('INPUT', 'LAUNCH');
  const deadline = started + (kind === 'api' ? L.apiDeadlineMs : L.cliDeadlineMs);
  let terminal = null, terminalAt = null, terminalCleanupDeadline = null, disposed = false, active = null;
  let publication = null;
  const publicationView = () => publication ? publicationStatus(publication.token) : null;
  let helpers = 0, workers = 0, helperUsedMs = 0, clockTimer = null;
  const events = [], stopListeners = new Set();
  const record = (type, detail = {}) => events.push(Object.freeze({ type, at: readNow(), ...detail }));
  const stop = (error, stage = 'EVALUATION', dispositionDeadline = null) => {
    if (!terminal) {
      terminal = operationalError(error, stage); terminalAt = readNow();
      terminalCleanupDeadline = dispositionDeadline ?? terminalAt + L.cleanupAllowanceMs;
      failureDeadlines.set(terminal, dispositionDeadline ?? performance.now() + L.cleanupAllowanceMs);
      clearTimeout(clockTimer);
      record('terminal', { code: terminal.code, stage: terminal.stage });
      for (const listener of stopListeners) listener(terminal);
    }
    return terminal;

const checkpoint = (stage = 'EVALUATION', limit = active?.deadline ?? deadline) => {
  if (terminal) throw terminal;
  if (disposed) throw stop(new ReadinessError('INTERNAL', stage));
  const current = readNow();
  // An abort callback is itself a checkpoint. Equal-time first observation
  // chooses TIMEOUT; a previously terminal CANCELLED can never be replaced.
  const status = publicationView();
  const interruption = current >= Math.min(deadline, limit) ? 'TIMEOUT' : signal?.aborted ? 'CANCELLED' : null;
  if (interruption && status?.admitted) {
    const observed = [];
    if (current >= Math.min(deadline, limit) && !status.deadlineExpiredAfterAdmission) observed.push('MO1307_TIMEOUT');
    if (signal?.aborted && !status.cancelledAfterAdmission) observed.push('MO1307_CANCELLED');
    for (const code of observed) {
      recordPublicationInterruption(publication.token, code);
      record('publication-interruption', { code, phase: status.phase });
    }
    // An admitted rename owns settlement. Neither terminal failure nor the
    // two-second disposition clock can start before its actual outcome.
    if (!publication.transport) throw new ReadinessError(interruption, stage);
    throw stop(new ReadinessError('OUTPUT', 'PUBLICATION'));
  }
  if (interruption) throw stop(new ReadinessError(interruption, stage));
  return current;
};
const arm = () => {
  clearTimeout(clockTimer);
  if (disposed || terminal) return;
  const stage = active?.stage ?? 'EVALUATION';
  const limit = Math.min(deadline, active?.deadline ?? deadline);
  clockTimer = setTimeout(() => {
    try { checkpoint(stage, limit); arm(); } catch { /* stop wakes the owner */ }
  }, Math.max(1, Math.ceil(limit - readNow())));
  clockTimer.unref?.();
};
const onAbort = () => { try { checkpoint(active?.stage ?? 'LAUNCH'); } catch { /* terminal */ } };
signal?.addEventListener('abort', onAbort, { once: true });
arm();

const cleanup = async (owner) => {
  const cleanupDeadline = terminalAt + L.cleanupAllowanceMs;
  let timer;
  try {
    try { owner.terminate?.(); } catch { /* still require closed observation */ }
    const remaining = Math.max(0, cleanupDeadline - readNow());
    const result = await Promise.race([
      Promise.resolve(owner.closed).then(() => true, () => false),
      new Promise(resolve => { timer = setTimeout(() => resolve(false), remaining); }),
    ]);
    owner.cleanupConfirmed = result === true && readNow() <= cleanupDeadline && owner.quiescence();
    if (!owner.cleanupConfirmed) owner.abandon?.();
    record('cleanup', { role: owner.kind, confirmed: owner.cleanupConfirmed });
  } finally { clearTimeout(timer); }

const runOwned = async (role, start, { stage = role === 'helper' ? 'ACQUISITION' : 'EVALUATION' } = {}) => {
  if (publicationView()?.admitted) throw new ReadinessError('INTERNAL', stage);
  checkpoint(stage);
  if (!['helper', 'worker'].includes(role) || typeof start !== 'function' || active
      || (role === 'helper' && kind !== 'cli') || (role === 'worker' && workers !== 0)) {
    throw stop(new ReadinessError('INTERNAL', stage));
  }
  const launch = readNow();
  const limit = role === 'helper'
    ? Math.min(deadline, launch + L.helperDeadlineMs, launch + L.helperAggregateDeadlineMs - helperUsedMs)
    : Math.min(deadline, launch + L.apiDeadlineMs);
  checkpoint(stage, limit);
  const owner = { kind: role, deadline: limit, stage, launch, terminate: null, closed: null, cleanupConfirmed: false, quiescence: () => true, abandon: null };
  active = owner;
  role === 'helper' ? helpers += 1 : workers += 1;
  let wake, settleOwner;
  owner.settled = new Promise(resolve => { settleOwner = resolve; });
  const stopped = new Promise((_, reject) => { wake = reject; stopListeners.add(wake); });
  // Install the rejecting promise before starting so synchronous launch abort
  // cannot lose cancellation. The catch also prevents an abandoned rejection.
  stopped.catch(() => {});
  record('start', { role, deadline: limit, ordinal: role === 'helper' ? helpers : workers });
  arm();
  try {
    const child = start(Object.freeze({ deadline: limit, checkpoint: () => checkpoint(stage, limit),
      fail: error => stop(error, stage), observe: detail => record('observation', { role, ...detail }) }));
    if (!child || typeof child.terminate !== 'function' || !child.completion || !child.closed) fail('INTERNAL', stage);
    owner.terminate = child.terminate; owner.closed = child.closed;
    owner.quiescence = child.quiescence ?? (() => true); owner.abandon = child.abandon;
    const result = await Promise.race([child.completion, stopped]);
    // completion is not authority for exit: closed must separately settle.
    await Promise.race([child.closed, stopped]);
    checkpoint(stage, limit);
    if (!owner.quiescence()) fail('INTERNAL', stage);
    owner.cleanupConfirmed = true;
    if (role === 'helper') helperUsedMs += readNow() - launch;
    record('quiescent', { role, ordinal: role === 'helper' ? helpers : workers });
    return result;
  } catch (error) {
    stop(error, stage);
    if (owner.closed) await cleanup(owner);
    else { owner.cleanupConfirmed = true; record('cleanup', { role, confirmed: true, launchFailed: true }); }
    throw terminal;
  } finally {
    stopListeners.delete(wake);
    if (owner.cleanupConfirmed) active = null;
    settleOwner(); arm();
  }
};

export function helperLaunchSpecification() {
  return Object.freeze({ executable: WINDOWS_INSTALLATION.powershell,
    args: Object.freeze(['-NoLogo', '-NoProfile', '-NonInteractive', '-ExecutionPolicy', 'Bypass', '-File', SCRIPT]),
    options: Object.freeze({ cwd: DIRECTORY, env: Object.freeze({ SystemRoot: WINDOWS_INSTALLATION.windowsDirectory,
      WINDIR: WINDOWS_INSTALLATION.windowsDirectory }), windowsHide: true, detached: false,
      shell: false, stdio: Object.freeze(['pipe', 'pipe', 'pipe']) }) });
}

export function createHelperTransport(supervisor) { return transport(supervisor, spawn); }
// Internal engineering doubles are not reachable from API/CLI options.
export function createHelperTransportForTesting(supervisor, spawnDouble) { return transport(supervisor, spawnDouble); }

exchange(frame) {
  supervisor.checkpoint('ACQUISITION');
  const request = decodeHelperRequest(frame);
  const detached = Buffer.from(frame);
  return supervisor.runOwned('helper', lease => {
    // Hidden pipes still create an attributable Windows console host here.
    // The fixed helper natively detaches and confirms that host's exit
    // before emitting any valid response. It launches no other children.
    const child = launch(specification.executable, [...specification.args], {
      ...specification.options, env: { ...specification.options.env }, stdio: [...specification.options.stdio],
    });
    let resolveClosed, resolveCompletion, rejectCompletion;
    const closed = new Promise(resolve => { resolveClosed = resolve; });
    const completion = new Promise((resolve, reject) => { resolveCompletion = resolve; rejectCompletion = reject; });
    const chunks = [];
    let total = 0, stderrBytes = 0, outputEnded = false, errorEnded = false, inputFinished = false;
    let outputClosed = false, errorClosed = false, inputClosed = false, processClosed = false;
    let processCode = null, streamFailure = null, consoleQuiescent = false;
    const rejected = code => {
      const error = new ReadinessError(code, 'ACQUISITION'); streamFailure ??= error; lease.fail(error);
    };
    const finish = () => {
      if (!processClosed || !outputClosed || !errorClosed || !inputClosed) return;
      // A validated frame can prove prior native console quiescence even
      // after terminal cancellation; it can NEVER restore success.
      let responseBytes;
      try {
        if (outputEnded && total <= L.helperResponseBytes) {
          responseBytes = Buffer.concat(chunks, total);
          decodeHelperResponse(responseBytes, request); consoleQuiescent = true;
        }
      } catch { /* No console proof from malformed/partial transport. */ }
      resolveClosed();
      try {
        if (streamFailure) throw streamFailure;
        if (processCode !== 0 || !outputEnded || !errorEnded || !inputFinished) fail('INTERNAL', 'ACQUISITION');
        lease.checkpoint();
        if (!consoleQuiescent) fail('INPUT', 'ACQUISITION');
        lease.checkpoint();
        resolveCompletion({ responseBytes, exitConfirmed: true });
      } catch (error) { rejectCompletion(error); }

  child.stdout.on('data', data => {
    total += data.byteLength;
    if (total > L.helperResponseBytes) { rejected('RESOURCE_LIMIT'); return; }
    chunks.push(data);
    // Once enough prefix bytes exist, reject an oversized advertised body
    // before waiting for attacker-controlled completion or allocation.
    if (total >= 4 && chunks.length < 5) {
      const prefix = Buffer.concat(chunks, Math.min(total, 4));
      if (prefix.readUInt32BE(0) + 4 > L.helperResponseBytes) rejected('RESOURCE_LIMIT');
    }
  });
  child.stderr.on('data', data => {
    stderrBytes += data.byteLength;
    if (stderrBytes > L.stderrBytes) rejected('RESOURCE_LIMIT');
  });
  child.stdout.once('end', () => { outputEnded = true; });
  child.stderr.once('end', () => { errorEnded = true; });
  child.stdin.once('finish', () => { inputFinished = true; });
  child.stdout.once('close', () => { outputClosed = true; finish(); });
  child.stderr.once('close', () => { errorClosed = true; finish(); });
  child.stdin.once('close', () => { inputClosed = true; finish(); });
  for (const stream of [child.stdin, child.stdout, child.stderr]) stream.on('error', () => rejected('INTERNAL'));
  child.once('error', () => rejected('INTERNAL'));
  child.once('close', code => { processClosed = true; processCode = code; finish(); });
  lease.observe({ pid: child.pid ?? null, consolePolicy: 'HELPER_NATIVE_DETACH_AND_CONFIRMED_HOST_EXIT' });
  child.stdin.end(detached);
  return { completion, closed, quiescence: () => consoleQuiescent, abandon: () => child.unref?.(), terminate: () => {
    child.stdin.destroy(); child.stdout.destroy(); child.stderr.destroy();
    if (!processClosed) child.kill();
  } };
}, { stage: 'ACQUISITION' });

export function createHelperSequence(command, { session = randomBytes(32).toString('hex'), now = () => performance.now() } = {}) {
  if (!['evaluate', 'verify'].includes(command) || typeof session !== 'string' || !SESSION.test(session) || typeof now !== 'function') reject();
  const start = now();
  if (!Number.isFinite(start)) reject();
  const state = { command, session, next: 1, active: null, awaitingExit: false, failed: false,
    worker: 'NOT_STARTED', output: null, parent: null, claimed: false, usedMs: 0, launched: null, last: start };
  const terminal = fn => { try { if (state.failed) reject(); return fn(); } catch (error) { state.failed = true; throw error; } };
  const checkpoint = () => terminal(() => {
    const current = now();
    if (!Number.isFinite(current) || current < state.last) reject();
    state.last = current;
    if (current >= start + LIMITS.cliDeadlineMs || (state.launched !== null
        && (current >= state.launched + LIMITS.helperDeadlineMs
          || state.usedMs + current - state.launched >= LIMITS.helperAggregateDeadlineMs))) fail('TIMEOUT', 'ACQUISITION', null);
    return current;
  });
  const api = Object.freeze({
    session,
    begin(request) { return terminal(() => {
      const current = checkpoint();
      validateHelperRequest(request);
      if (state.active || state.awaitingExit || state.worker === 'RUNNING'
          || state.next > (command === 'evaluate' ? LIMITS.helperRequests : LIMITS.helperVerifyRequests)
          || request.sequence !== state.next || request.session !== session
          || (state.next <= 4 && state.worker !== 'NOT_STARTED')
          || (state.next > 4 && state.worker !== 'STOPPED')
          || (state.next === 4 && request.operation !== (command === 'evaluate' ? 'CHECK_OUTPUT' : 'READ_SET'))) reject();
      if (state.usedMs >= LIMITS.helperAggregateDeadlineMs) fail('TIMEOUT', 'ACQUISITION', null);
      const encoded = encodeHelperRequest(request);
      const copy = decodeHelperRequest(encoded);
      if (state.next === 4 && command === 'evaluate') state.output = validateAbsoluteRoot(copy.roots[0].path);
      if (state.next > 4 && validateAbsoluteRoot(copy.roots[0].path) !== state.output) reject('FILESYSTEM_BOUNDARY');
      state.active = copy; state.launched = current; state.next += 1;
      return encoded;
    }); },
    complete(bytes) { return terminal(() => {
      checkpoint();
      if (!state.active || state.awaitingExit) reject();
      const response = decodeHelperResponse(bytes, state.active);
      if (response.status === 'ERROR') { state.failed = true; return response; }
      if (state.active.sequence === 4 && command === 'evaluate') state.parent = structuredClone(response.roots[0].chain);
      if (state.active.sequence === 5) {
        const chain = response.roots[0].chain;
        if (chain.length !== state.parent.length) reject('FILESYSTEM_BOUNDARY');
        chain.forEach((item, index) => assertStableIdentity(state.parent[index], item, { directory: true }));
      }
      state.active = null; state.awaitingExit = true;
      checkpoint();
      return response;
    }); },
    helperExited() { return terminal(() => {
      const current = checkpoint();
      if (!state.awaitingExit || state.active || state.launched === null) reject();
      state.usedMs += current - state.launched;
      state.launched = null; state.awaitingExit = false;
    }); },

async function read(slot, requestRoots, files, operation = 'READ_SET') {
  const stage = slot < 3 ? 'CONFIGURATION' : 'ACQUISITION';
  checkpoint(stage);
  try {
    const frame = sequence.begin({ kind: 'MemoryOSReadinessHelperRequest', version: '2.0.0',
      session: sequence.session, sequence: slot, operation, roots: requestRoots, files });
    const answer = await exchange(frame);
    if (!answer || answer.exitConfirmed !== true || Object.keys(answer).sort().join(',') !== 'exitConfirmed,responseBytes') fail('INTERNAL', stage);
    const response = sequence.complete(answer.responseBytes);
    if (response.status === 'ERROR') {
      if (operation === 'CHECK_OUTPUT') fail('OUTPUT', 'PUBLICATION');
      throw new ReadinessError(response.code, stage);
    }
    sequence.helperExited();
    checkpoint(stage);
    if (operation !== 'READ_SET') return response;
    for (const root of response.roots) {
      if (roots.has(root.id)) assertStableIdentity(roots.get(root.id), root.identity, { directory: true, stage });
      else roots.set(root.id, root.identity);
    }
    const snapshots = Object.create(null);
    for (const entry of response.files) {
      const key = entry.identity.volumeSerial + ':' + entry.identity.fileId;
      if (identities.has(key)) fail('FILESYSTEM_BOUNDARY', stage, entry.id);
      identities.add(key);
      snapshots[entry.id] = Buffer.from(entry.bytes.join(''), 'base64');
    }
    return snapshots;
  } catch (error) { sequence.abort(); throw error; }

